# Replays the real history.py score rule over the real ping outcomes (T=taken, D=turned down, M=missed)
CREDIT, PEN = 0.08, 0.12
pre = {"Captain Vantage":"TTDTTDTTTTTTTTTTDTMTTTTDTTTTDTDDTTDTTTDDTTTMDTTTTTTTTTDTDTTDDTTTTTTTTDTDTDTT","Cindermark":"TTDDTTTTTTTTTTTTDTTTTTDMTTTTTDTTDTTDTTTTTTDTDTTTTTDTTTTDT","Corporal Ashgrove":"TTTTDDTTTTTTTDDTTTTTTTTTMDTTTTDTDDTTTTTTDTTTTTTTDTTTTTDDTTTTTTD","Farlight":"TDTDDTTTTTTTTTDTTTDDTTTTTMTTTTDDTTTTTTTMTTDTDTTTTDTTTTTDTDTTDTTTTTTDTMTDTTD","Halfmoon":"TTTDTTTTTDDTTDTTTDDTTTTTTTDDDTTTTTTDDDTTDTTTTTTTTTTDTTDDTDTTTTTTDTTTD","Ironvale":"DTTTTTTDTDTDDTTTTTDTTTTTTTDDTTTTTTDTTMTTTTTTTTDTDTT","Meteor Mite":"TDTTTDDDTTTTTTTTTDTDTTDTDTDTTTTDDTTMDTTTDDTTTTTTMTTDTTTDTTDTDTDTTTTDTT","Nightwell":"TTMTTTTDTTTDTDTTTDDTTDTDTTTTTMTTTTDTTTTTTDTTTTDTTTTTTTDTMDTTTTTDTTDTTDDTTTTTDTTDTTTTTTTTDTTTTDT","Sgt. Bulwark":"TDTTTTTDTTTTTDTDTTTDTDTTTTTTTDTTTDTTTDTDTDTTTTTTTTTTDDDTT","Sgt. Falkirk":"TTTTTTTMTTTMTTTTDTTTTTDDDTTTTTTDTTDTTTTTTTTDTTDTTTTTTDTDTTTTDTT","Stormwrack":"TTTTTTDTTTDDTTTTTDDTTTTTTTTTTTTDDTDTTTDDTTTTTTTTTTTTTTTDTDDTTTTTTDTTTTTTDTTTDTTTTD","The Drift":"TTTTDTDTTTTTTDTTTTTTTDTTTTTTTTDMTTTTTTT","The Gale":"TTTTDTTTTTMDTTDTDTDTTTTTTTTTDTDTTTTTDTDTDTTTTMTTTTTTTTTTTTTTTTMDTTDTTTTDDTTTTTTTMT","The Longcast":"DTDTTTTTMTTTTDTTTTTTDTDTTTTTDTTDTTTDTDTDTTTTT","The Undertow":"TTDTTDDTTTTTTDTTTTTDTTTTMTTTTTDDTTTDDTTTTTTTTTDTTTTTTTTTDDTTTDTTDTDTTTTTTTD","Vesper":"TDTTTTTTTTDTTDTMTTTTTDTTDTTTTTTTTTDTTMTTTTDDTTTTTTTTTDTTTTTTTTMTTTTTDTTTTTTTTDTTTDTTDT"}
post = {"Captain Vantage":"DMDTTTTTDTTTMTMDTTTTTTDTTTTMTTTDTTDTTTTTDTTDTTTTMTTDTTTDMTT","Cindermark":"DTDTTMTTTTTTTMTDDTTTDTTDTTMMTTTTDDTTTTTTMT","Corporal Ashgrove":"TTDMDTTTDTTMDTTMTTTTDTMDTTTTT","Farlight":"TMDMMMTMDMM","Halfmoon":"DMTTTMDTTDMTTTDTMTTTDTDTMTTTDTTTT","Ironvale":"TDMTDTTTTMDMDTTTTTTMDTTTMTTTTTTTTTTMMTD","Meteor Mite":"DMMMTTMDTMMDMM","Nightwell":"TTTDDTMMDDTMTDTTTTTDTTTTTTMTTTTTTTTDTDDDTTTMTTMTDTDTMTTDDTTTDTTTTTTTTM","Sgt. Bulwark":"MTTDMDTTTDTTTTTMTDTDMTTMTTTTMTDTTTMTTTT","Sgt. Falkirk":"DTTMTMTTTTDTTTDTMTTTMDTMTTTTTTTDMTTTTTTTTDTTTMTDTTDM","Stormwrack":"TTTMMMDTTDDTTDTTTTTTMMTTTTTTTDTMTMDTTTDTTTTTTTMTTTTTDTTTTTTTTDM","The Drift":"MTDMTTTTMTTDTTTTTDMTTTMTTDDT","The Gale":"MMTTTDTDTDTTTDTTTTDMDTTTTMTTTMMTTDTTTDTTTTTDDTTTDDTTTMTTTMTTTTTTTTTDT","The Longcast":"TTDTDMTTTMTDTTMMDTTTDTTMTTTTTTDT","The Undertow":"MMTTMMMDDTMMMM","Vesper":"MTMTDTMMTTMMDMDMM"}
four = {"Farlight","The Undertow","Meteor Mite","Vesper"}
def step(h, c): return min(1.0, h+CREDIT) if c == "T" else max(0.0, h-PEN)
def replay(seq, h):
    for c in seq: h = step(h, c)
    return h
print(f"{'responder':18} {'H@12Aug':>8} {'H end A':>8} {'H end B(reset .5)':>18} {'pings after 12Aug':>18} {'pings to floor(B)':>18}")
rows = []
for n in pre:
    h0 = replay(pre[n], 0.5)            # A: scores carried across the release
    hA = replay(post[n], h0)
    h, hit = 0.5, None                  # B: scores reset to 0.5 at the 4.2 deploy (in-memory dict)
    for i, c in enumerate(post[n], 1):
        h = step(h, c)
        if h == 0 and hit is None: hit = i
    rows.append((n, h0, hA, h, len(post[n]), hit))
for n, h0, hA, hB, k, hit in sorted(rows, key=lambda r: r[2]):
    print(f"{n+(' *' if n in four else ''):18} {h0:8.2f} {hA:8.2f} {hB:18.2f} {k:18d} {str(hit):>18}")
